"""Writes fixtures/labels.json: openFDA-shaped records for the 19 demo labels
plus Janumet XR (context only, so 'Janumet' has two product groups).

Every value below was read from the live openFDA API on 2026-11-05. Text fields
are short excerpts (the part that names the dosage form, and the full Recent
Major Changes line), not whole labels. Real ingestion reads complete records
with the same field names.
"""
import json, pathlib

def rec(ds, spl_id, set_id, version, eff, brand, generic, substance, mfr, orig,
        ptype, route, pndc, kndc, desc, hs, pkg, rmc, bw, wc, warn):
    of = {"brand_name": brand, "generic_name": generic, "substance_name": substance,
          "manufacturer_name": [mfr], "product_ndc": pndc, "package_ndc": kndc,
          "route": route, "product_type": [ptype]}
    if orig: of["is_original_packager"] = [True]
    r = {"_demo_id": ds, "id": spl_id, "set_id": set_id, "version": version,
         "effective_time": eff, "openfda": of}
    if desc: r["description"] = [desc]
    if hs: r["how_supplied"] = [hs]
    if pkg: r["package_label_principal_display_panel"] = [pkg]
    if rmc: r["recent_major_changes"] = [rmc]
    if bw: r["boxed_warning"] = ["(present)"]
    if wc: r["warnings_and_cautions"] = ["(present)"]
    if warn: r["warnings"] = ["(present)"]
    return r

